import{_ as a,a as r,b as i,c as e,d as o,e as d}from"./chunks/chat-setting-02.QfVwD9xB.js";import{_ as s}from"./chunks/chat.CwIZ8ihr.js";import{_ as n,a as l,b as g,c,d as p,e as h,f,g as m}from"./chunks/reply-images-setting-05.BOgot54n.js";import{_ as u,o as _,c as b,a3 as v}from"./chunks/framework.D1iekJsc.js";const $=JSON.parse('{"title":"聊天","description":"MiniTavern 聊天与会话：开聊、流式回复、续写重生成、气泡操作；手机上的 AI 角色扮演对话主界面。","frontmatter":{"title":"聊天","description":"MiniTavern 聊天与会话：开聊、流式回复、续写重生成、气泡操作；手机上的 AI 角色扮演对话主界面。","head":[["meta",{"name":"keywords","content":"酒馆,AI酒馆,Ai酒馆,迷你酒馆,超迷你酒馆,MiniTavern,AI伙伴,AI朋友,Ai本地聊天,AI本地聊天,Silly Tavern,SillyTavern,手机玩Silly Tavern,Silly Tavern手机版,Silly Tavern安卓,Silly Tavern苹果,AI角色扮演,角色卡,角色扮演,AI聊天,手机AI,离线AI,AI剧情,本地大模型,本地模型,Ollama,LM Studio,世界书,正则,BYOK,用户手册,教程,character card,AI roleplay,AI companion,tavern AI"}],["meta",{"property":"og:title","content":"聊天 · MiniTavern Docs"}],["meta",{"property":"og:description","content":"MiniTavern 聊天与会话：开聊、流式回复、续写重生成、气泡操作；手机上的 AI 角色扮演对话主界面。"}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/manual/chat"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/manual/chat"}]]},"headers":[],"relativePath":"manual/chat.md","filePath":"manual/chat.md","lastUpdated":1787816217000}'),y={name:"manual/chat.md"};function A(T,t,q,x,I,k){return _(),b("div",null,[...t[0]||(t[0]=[v('<h1 id="聊天" tabindex="-1">聊天 <a class="header-anchor" href="#聊天" aria-label="Permalink to &quot;聊天&quot;">​</a></h1><p>路径：底部 Tab <strong>聊天</strong>；对话页为单会话主界面。</p><h2 id="会话列表" tabindex="-1">会话列表 <a class="header-anchor" href="#会话列表" aria-label="Permalink to &quot;会话列表&quot;">​</a></h2><p><img src="'+a+'" alt="聊天列表"></p><ul><li>搜索、置顶、克隆、删除会话。</li><li>右上角 <strong>+</strong> 可新建聊天、<strong>从存档导入</strong>、<strong>从文件导入</strong>（详见 <a href="./chat-archive">聊天存档</a>）。</li></ul><h2 id="对话页常用操作" tabindex="-1">对话页常用操作 <a class="header-anchor" href="#对话页常用操作" aria-label="Permalink to &quot;对话页常用操作&quot;">​</a></h2><p><img src="'+s+'" alt="对话页"></p><table tabindex="0"><thead><tr><th>操作</th><th>说明</th></tr></thead><tbody><tr><td>发送</td><td>用户消息 → 请求模型 → 流式或完整显示回复</td></tr><tr><td>续写</td><td>在当前助手回复末尾继续生成</td></tr><tr><td>重生成</td><td>替换最近助手回复（以 UI 为准）</td></tr><tr><td>智能回复</td><td>生成建议填入输入框，不直接变成助手消息</td></tr><tr><td>取消</td><td>取消进行中的生成</td></tr><tr><td>重新开始</td><td>清空并按开场白重开</td></tr></tbody></table><p>开场白若有多条，开聊时可选择。</p><h2 id="图片-发送与气泡" tabindex="-1">图片：发送与气泡 <a class="header-anchor" href="#图片-发送与气泡" aria-label="Permalink to &quot;图片：发送与气泡&quot;">​</a></h2><p>输入区 <strong>+</strong> 打开附件菜单：相册、拍照，以及生图相关入口（需已配置生图连接时可用）。</p><div class="shot-flow"><figure class="shot-step"><img src="'+r+'" alt="加号附件菜单"><figcaption>1 · 加号 · 相册 / 拍照</figcaption></figure><figure class="shot-step"><img src="'+i+'" alt="图文气泡"><figcaption>2 · 附图 + 文字发出</figcaption></figure></div><table tabindex="0"><thead><tr><th>方式</th><th>说明</th></tr></thead><tbody><tr><td>普通附图</td><td>选图后缩略图挂在输入框上方，配文字发出 → <strong>图文气泡</strong></td></tr><tr><td>纯图气泡</td><td>部分生图结果以 <strong>纯图气泡</strong> 展示，可停止生成</td></tr><tr><td>长按气泡图片</td><td>短按预览，长按出菜单</td></tr></tbody></table><ul><li>若本聊开了「回复图片」，智能/关键词触发出图时，你附的图可作 <strong>风格参考</strong>。</li><li>若输入是 <code>/imagine …</code>，附图只作生图参考，<strong>不会</strong>当成一条用户消息发出。</li></ul><p>更完整的生图入口表见 <a href="./model-link#生图连接--回复图片--关键词">模型连接 · 生图</a>。</p><h2 id="图片描写-识图" tabindex="-1">图片描写（识图） <a class="header-anchor" href="#图片描写-识图" aria-label="Permalink to &quot;图片描写（识图）&quot;">​</a></h2><p>当主模型<strong>不支持</strong>视觉、或你希望统一走「图转文」时，可用 <strong>图片描写</strong>。</p><p>全局：<strong>设置 → 聊天设置 → 识图设置</strong> → 开启「图片描写」并配置描写模型与提示词。</p><div class="shot-flow"><figure class="shot-step"><img src="'+n+'" alt="进入识图设置"><figcaption>1 · 设置页选择聊天设置</figcaption></figure><figure class="shot-step"><img src="'+l+'" alt="图片描写"><figcaption>2 · 选择识图设置</figcaption></figure><figure class="shot-step"><img src="'+g+'" alt="描写模型"><figcaption>3 · 描写模型与提示词</figcaption></figure></div><p>单聊可在 <strong>聊天设置 → 识图与显示</strong> 跟随默认或单独覆盖（描写模型与提示词仍用全局）。</p><table tabindex="0"><thead><tr><th>状态</th><th>行为</th></tr></thead><tbody><tr><td>关闭描写</td><td>模型支持视觉时，多模态直接把图送给主模型</td></tr><tr><td>开启描写</td><td>主模型不支持图片参数时：先由描写模型图转文（可与识人同一次请求），再发主模型；结果缓存复用。主模型已支持视觉时仍多模态直传</td></tr></tbody></table><p>不支持图片的主模型 + 开启描写后的顺序：描写（+识人）→ 主聊天 → 若回复带生图数据再旁路生图。</p><p>报错「当前模型不支持图片」见 <a href="./errors#visionunsupported">错误排错 · visionUnsupported</a>。</p><h2 id="回复图片-自动出图" tabindex="-1">回复图片（自动出图） <a class="header-anchor" href="#回复图片-自动出图" aria-label="Permalink to &quot;回复图片（自动出图）&quot;">​</a></h2><p>路径：<strong>设置 → 生图 → 生图设置</strong> → <strong>回复图片</strong>：先打开开关，再选触发方式。</p><div class="shot-flow"><figure class="shot-step"><img src="'+c+'" alt="生图设置"><figcaption>1 · 设置页选择生图</figcaption></figure><figure class="shot-step"><img src="'+p+'" alt="回复图片"><figcaption>2 · 生图设置</figcaption></figure><figure class="shot-step"><img src="'+h+'" alt="触发方式"><figcaption>3 · 生图模型连接配置</figcaption></figure><figure class="shot-step"><img src="'+f+'" alt="画质参数"><figcaption>4 · 回复图片与生图配置</figcaption></figure><figure class="shot-step"><img src="'+m+'" alt="转写模板"><figcaption>5 · 回复图片关键词</figcaption></figure></div><p>对话中自动出图效果见 <a href="./model-link#生图连接--回复图片--关键词">模型连接 · 生图</a>；也可在聊天里用 <code>/imagine</code> 或附件菜单手动出图。</p><table tabindex="0"><thead><tr><th>触发方式</th><th>说明</th></tr></thead><tbody><tr><td><strong>智能判断</strong></td><td>由模型根据对话判断是否出图；画幅按场景（自拍 3:4、相机 3:2 等），命中后 1 张</td></tr><tr><td><strong>关键词触发</strong></td><td>用户消息命中关键词规则时出图；需在生图设置里同时开启回复图片并选关键词模式</td></tr></tbody></table><p>关闭「回复图片」后，聊天不会<strong>自动</strong>出图；<code>/imagine</code>、附件菜单生图、长按气泡生图仍可用。</p><p>聊天内其它生图入口：</p><table tabindex="0"><thead><tr><th>入口</th><th>说明</th></tr></thead><tbody><tr><td><code>/imagine 提示词</code></td><td>主模型先判断是否相关、是否用角色/用户参考图，再拼提示词生图；可先附图作参考</td></tr><tr><td><code>/imagine scene</code> / 附件 → 根据故事</td><td>按近期对话画当前这一幕</td></tr><tr><td><code>/imagine last</code> / 附件 → 根据最后消息</td><td>按最后一条消息来画</td></tr><tr><td>附件 → 生成背景图</td><td>环境背景，完成后可设为聊天背景</td></tr><tr><td>长按气泡 → 生图</td><td>按这条气泡来画</td></tr></tbody></table><p>未配置生图连接时，附件生图与 <code>/imagine</code> 会提示去设置。云端免费档见 <a href="/ultra_guides/free-cloud/#免费生图怎么配">免费云端 · 生图</a>；本机见 <a href="/ultra_guides/local/image-gen/">生图模型部署</a>。</p><h2 id="气泡菜单" tabindex="-1">气泡菜单 <a class="header-anchor" href="#气泡菜单" aria-label="Permalink to &quot;气泡菜单&quot;">​</a></h2><p><img src="'+e+'" alt="气泡菜单"></p><p>长按或菜单：复制、编辑、隐藏、删除等。隐藏消息通常不再展示（对上下文的影响以实现为准）。</p><h2 id="聊天设置-按会话" tabindex="-1">聊天设置（按会话） <a class="header-anchor" href="#聊天设置-按会话" aria-label="Permalink to &quot;聊天设置（按会话）&quot;">​</a></h2><p>入口：对话页右上角或设置入口 → <strong>聊天设置</strong>。</p><div class="shot-flow"><figure class="shot-step"><img src="'+o+'" alt="聊天设置入口"><figcaption>1 · 聊天设置</figcaption></figure><figure class="shot-step"><img src="'+d+'" alt="会话配置项"><figcaption>2 · 模型 / 世界书 / 正则等</figcaption></figure></div><table tabindex="0"><thead><tr><th>子项（文案以 App 为准）</th><th>作用</th></tr></thead><tbody><tr><td>角色详情</td><td>查看本聊角色快照 / 导出等</td></tr><tr><td>用户身份</td><td>跟随默认人设或指定</td></tr><tr><td>语言模型</td><td>跟随默认语言模型或指定连接 / 参数</td></tr><tr><td>生图模型</td><td>跟随默认生图，或单独选连接、生图设置与关键词规则</td></tr><tr><td>正则</td><td>多选全局正则组；<strong>空选 = 关闭</strong></td></tr><tr><td>世界书</td><td>多选全局世界书；<strong>空选 = 不注入</strong></td></tr><tr><td>变量管理</td><td>本聊 / 全局宏变量</td></tr><tr><td>前端渲染</td><td>HTML / 脚本相关开关</td></tr><tr><td>识图与显示 / 背景</td><td>识图与聊天外观</td></tr><tr><td>底部 <strong>存档</strong></td><td>导出本聊为聊天存档（另见 <a href="./chat-archive">聊天存档</a>）</td></tr></tbody></table><h2 id="出错时" tabindex="-1">出错时 <a class="header-anchor" href="#出错时" aria-label="Permalink to &quot;出错时&quot;">​</a></h2><p>气泡错误态可打开 <strong>查看详情</strong>，对照 <a href="./errors">错误代码排错</a>。斜杠生图失败会留在原气泡上可重试；附件菜单、智能/关键词生图失败仅在当前打开 App 期间保留。</p>',41)])])}const B=u(y,[["render",A]]);export{$ as __pageData,B as default};
